window.CODE = Object.assign(window.CODE || {}, {"ch42/agents_check.py":"\"\"\"Check subagent definition files (.claude/agents/*.md) against the rules on Claude Code's sub-agents page (read 5 Nov 2026).\n\n    python agents_check.py starter/.claude/agents --readonly planner,reviewer\n\nA subagent file is Markdown with a YAML header. The header decides what the helper may do, which is why\nthe checks here are about power: a reviewer that can edit files is no longer an independent reviewer.\n\"\"\"\nfrom __future__ import annotations\n\nimport re\nimport sys\nfrom pathlib import Path\n\nimport yaml\n\nFIELDS = {\"name\", \"description\", \"tools\", \"disallowedTools\", \"model\", \"permissionMode\", \"maxTurns\", \"skills\", \"mcpServers\",\n          \"hooks\", \"memory\", \"effort\", \"isolation\", \"background\", \"omitClaudeMd\"}\nKNOWN_TOOLS = {\"Read\", \"Write\", \"Edit\", \"MultiEdit\", \"NotebookEdit\", \"Bash\", \"Grep\", \"Glob\", \"WebFetch\", \"WebSearch\", \"Agent\", \"Task\"}\nWRITE_TOOLS = {\"Write\", \"Edit\", \"MultiEdit\", \"NotebookEdit\", \"Bash\"}\nMODELS = {\"sonnet\", \"opus\", \"haiku\", \"fable\", \"inherit\"}\n\n\ndef _tools(value) -> list[str]:\n    if value is None:\n        return []\n    items = value if isinstance(value, list) else str(value).split(\",\")\n    return [re.sub(r\"\\(.*\\)$\", \"\", str(t).strip()) for t in items if str(t).strip()]\n\n\ndef check_file(path: Path, readonly: set[str] = frozenset()) -> list[str]:\n    text = path.read_text()\n    m = re.match(r\"^---\\n(.*?)\\n---\\n(.*)$\", text, re.S)\n    if not m:\n        return [f\"ERROR {path.name}: must start with a --- header.\"]\n    meta = yaml.safe_load(m.group(1)) or {}\n    body = m.group(2).strip()\n    out = []\n    name = meta.get(\"name\")\n    if not name or not meta.get(\"description\"):\n        out.append(f\"ERROR {path.name}: 'name' and 'description' are required.\")\n    if name and not re.fullmatch(r\"[a-z][a-z0-9-]*\", str(name)):\n        out.append(f\"WARN  {path.name}: name '{name}' should be lowercase letters, digits and hyphens.\")\n    if name and name != path.stem:\n        out.append(f\"INFO  {path.name}: name '{name}' differs from the file name.\")\n    for k in meta:\n        if k not in FIELDS:\n            out.append(f\"WARN  {path.name}: unknown field '{k}'.\")\n    desc = str(meta.get(\"description\", \"\"))\n    if desc and not re.search(r\"(?i)\\buse\\b\", desc):\n        out.append(f\"WARN  {path.name}: the description should say WHEN to use this helper ('Use when ...'); the main agent decides to delegate from it.\")\n    tools = _tools(meta.get(\"tools\"))\n    for t in tools:\n        if t not in KNOWN_TOOLS and not t.startswith(\"mcp__\"):\n            out.append(f\"WARN  {path.name}: unknown tool '{t}'.\")\n    if \"tools\" not in meta:\n        out.append(f\"WARN  {path.name}: no 'tools' list, so it inherits every tool. Name only what the job needs.\")\n    if name in readonly and (set(tools) & WRITE_TOOLS or \"tools\" not in meta):\n        out.append(f\"ERROR {path.name}: '{name}' is meant to be read-only but may use {sorted(set(tools) & WRITE_TOOLS) or 'all tools'}.\")\n    model = meta.get(\"model\")\n    if model and str(model) not in MODELS and not str(model).startswith(\"claude-\"):\n        out.append(f\"WARN  {path.name}: model '{model}' is not one of {sorted(MODELS)} or a full model id.\")\n    if \"Edit\" in tools and meta.get(\"isolation\") != \"worktree\" and name == \"coder\":\n        out.append(f\"INFO  {path.name}: a helper that edits files may run in its own worktree (isolation: worktree) so parallel work cannot collide.\")\n    if meta.get(\"isolation\") not in (None, \"worktree\"):\n        out.append(f\"WARN  {path.name}: isolation '{meta.get('isolation')}' is not 'worktree'.\")\n    if len(body.splitlines()) > 60:\n        out.append(f\"INFO  {path.name}: {len(body.splitlines())} lines of instructions; short, specific prompts work better.\")\n    if not body:\n        out.append(f\"ERROR {path.name}: no instructions after the header.\")\n    return out\n\n\ndef check_folder(folder: str | Path, readonly: set[str] = frozenset()) -> list[str]:\n    files = sorted(Path(folder).glob(\"*.md\"))\n    out = [line for f in files for line in check_file(f, readonly)]\n    names = [yaml.safe_load(re.match(r\"^---\\n(.*?)\\n---\", f.read_text(), re.S).group(1)).get(\"name\") for f in files if f.read_text().startswith(\"---\")]\n    for n in {n for n in names if names.count(n) > 1}:\n        out.append(f\"ERROR two helpers are called '{n}'.\")\n    return out or [f\"OK    {len(files)} helper(s), no problems found.\"]\n\n\nif __name__ == \"__main__\":\n    ro = set(sys.argv[sys.argv.index(\"--readonly\") + 1].split(\",\")) if \"--readonly\" in sys.argv else set()\n    lines = check_folder(sys.argv[1], ro)\n    print(\"\\n\".join(lines))\n    sys.exit(1 if any(l.startswith((\"ERROR\", \"WARN\")) for l in lines) else 0)\n","ch42/demo_handoff.py":"\"\"\"A good handoff note and a vague one, checked.   python demo_handoff.py\"\"\"\nfrom handoff import Handoff, checkpoint, validate\n\ngood = Handoff(task=\"T1\", from_role=\"coder\", to_role=\"reviewer\", goal=\"Add an after-hours message tool to the helpdesk\",\n               done=[\"added after_hours_message() in triage.py\", \"added a test that failed before the change\"],\n               decisions=[\"a fixed string, not a model call: the emergency number must never be paraphrased\"],\n               files_changed=[\"triage.py\", \"test_triage.py\"], verify=[\"python -m pytest -q\"],\n               evidence=\"$ python -m pytest -q\\n[PASS exit=0 1.1s]\\n3 passed in 0.02s\", tokens_used=42_000)\nprint(good.to_markdown())\nprint(\"validate:\", validate(good, owned=[\"triage.py\", \"test_triage.py\"]) or \"OK\")\nprint(\"checkpoint:\", checkpoint(good))\n\nvague = Handoff(task=\"T1\", from_role=\"coder\", to_role=\"reviewer\", goal=\"fix it\", evidence=\"all tests pass\", files_changed=[\"Dockerfile\"])\nprint(\"\\nA vague note:\")\nfor p in validate(vague, owned=[\"triage.py\"]):\n    print(\"  -\", p)\nprint(\"checkpoint:\", checkpoint(vague))\n","ch42/handoff.py":"\"\"\"A handoff note: what one worker gives the next, as data a program can check.\n\nWhen the planner finishes and the coder starts, or the coder finishes and the reviewer starts, the new worker\nhas NOT seen the conversation. Everything it needs must be in the note. A vague note (\"done, please review\")\nis how a team of agents repeats work, loses decisions and passes along unverified claims.\n\n    note = Handoff(task=\"T1\", from_role=\"coder\", to_role=\"reviewer\", goal=\"...\", ...)\n    problems = validate(note, owned=[\"triage.py\"])\n    gate = checkpoint(note, policy)         # does a person have to look before this continues?\n\"\"\"\nfrom __future__ import annotations\n\nimport json\nimport re\nfrom dataclasses import asdict, dataclass, field\n\nSTATUSES = {\"ready\", \"blocked\", \"needs_human\"}\nPROTECTED = (\"migrations/\", \".github/\", \".claude/\", \"Dockerfile\", \".env\")\n\n\n@dataclass\nclass Handoff:\n    task: str\n    from_role: str\n    to_role: str\n    goal: str\n    status: str = \"ready\"\n    done: list[str] = field(default_factory=list)\n    decisions: list[str] = field(default_factory=list)          # choices made and WHY, so the next worker does not undo them\n    files_changed: list[str] = field(default_factory=list)\n    verify: list[str] = field(default_factory=list)             # exact commands that prove it works\n    evidence: str = \"\"                                          # their output, pasted (Chapter 39)\n    open_questions: list[str] = field(default_factory=list)\n    risks: list[str] = field(default_factory=list)\n    tokens_used: int = 0\n\n    def to_json(self) -> str:\n        return json.dumps(asdict(self), indent=2)\n\n    @classmethod\n    def from_json(cls, text: str) -> \"Handoff\":\n        return cls(**json.loads(text))\n\n    def to_markdown(self) -> str:\n        def block(title, items):\n            return f\"## {title}\\n\" + (\"\\n\".join(f\"- {i}\" for i in items) if items else \"- (none)\") + \"\\n\"\n        return (f\"# Handoff {self.task}: {self.from_role} -> {self.to_role}  [{self.status}]\\n\\n**Goal:** {self.goal}\\n\\n\"\n                + block(\"Done\", self.done) + block(\"Decisions and why\", self.decisions) + block(\"Files changed\", self.files_changed)\n                + block(\"How to verify\", [f\"`{c}`\" for c in self.verify]) + (f\"## Evidence\\n```\\n{self.evidence}\\n```\\n\" if self.evidence else \"\")\n                + block(\"Open questions\", self.open_questions) + block(\"Risks\", self.risks) + f\"\\nTokens used: {self.tokens_used:,}\\n\")\n\n\ndef validate(n: Handoff, owned: list[str] | None = None) -> list[str]:\n    \"\"\"Problems that make this note unsafe to act on. Empty list = acceptable.\"\"\"\n    out = []\n    if n.status not in STATUSES:\n        out.append(f\"status must be one of {sorted(STATUSES)}\")\n    if len(n.goal.split()) < 4:\n        out.append(\"goal is too short to act on\")\n    if n.status == \"ready\" and n.from_role in (\"coder\", \"tester\"):\n        if not n.verify:\n            out.append(\"no verify commands: the next worker cannot check the claim\")\n        if not n.evidence.strip():\n            out.append(\"no evidence: paste the command output, not 'all tests pass'\")\n        elif re.search(r\"(?i)\\b(all|everything)\\b.*\\b(pass|passes|passed|ok)\\b\", n.evidence) and not re.search(r\"\\d+ passed|exit[= ]0|PASS\", n.evidence):\n            out.append(\"evidence is a claim, not output (no counts or exit codes)\")\n    if n.status == \"ready\" and not n.done:\n        out.append(\"'done' is empty\")\n    if n.files_changed and owned is not None:\n        outside = [f for f in n.files_changed if not any(f == p or (p.endswith(\"/\") and f.startswith(p)) for p in owned)]\n        if outside:\n            out.append(f\"changed files outside what this task owns: {outside}\")\n    if n.status == \"blocked\" and not n.open_questions:\n        out.append(\"blocked, but no open question says what is needed\")\n    return out\n\n\ndef checkpoint(n: Handoff, max_tokens: int = 200_000) -> tuple[bool, list[str]]:\n    \"\"\"(needs_a_person, reasons). The rule: a person must look when the cost of being wrong is high.\"\"\"\n    reasons = []\n    if n.status in (\"blocked\", \"needs_human\"):\n        reasons.append(f\"status is {n.status}\")\n    if n.open_questions:\n        reasons.append(\"open questions remain\")\n    if n.risks:\n        reasons.append(\"the worker listed risks\")\n    touched = [f for f in n.files_changed if f.startswith(PROTECTED) or f == \"Dockerfile\"]\n    if touched:\n        reasons.append(f\"protected files changed: {touched}\")\n    if n.tokens_used > max_tokens:\n        reasons.append(f\"token budget exceeded ({n.tokens_used:,} > {max_tokens:,})\")\n    return bool(reasons), reasons\n","ch42/parallel_demo.py":"\"\"\"Two stand-in workers change one repository at the same time, each in its own git worktree. Run:  python parallel_demo.py\n\nWHAT IS REAL: git (real worktrees, real branches, real merges), the ownership check, the tests that run on the result.\nWHAT IS A STAND-IN: the 'workers' are small scripts that write a fixed change. A real coding agent would take their place;\nthe plumbing around them is the part this file is about.\n\"\"\"\nfrom __future__ import annotations\n\nimport subprocess\nimport sys\nimport tempfile\nimport threading\nfrom pathlib import Path\n\nimport worktrees as wt\n\nBASE_FILES = {\n    \"triage.py\": 'def route(msg):\\n    return \"emergency\" if \"chest pain\" in msg.lower() else \"info\"\\n',\n    \"billing.py\": \"def total(items):\\n    return sum(items.values())\\n\",\n    \"test_triage.py\": 'from triage import route\\n\\n\\ndef test_chest_pain():\\n    assert route(\"I have chest pain\") == \"emergency\"\\n',\n    \"test_billing.py\": 'from billing import total\\n\\n\\ndef test_total():\\n    assert total({\"ECG\": 350, \"OPD\": 100}) == 450\\n',\n}\n\n\ndef make_repo(folder: Path) -> Path:\n    repo = folder / \"clinic\"\n    repo.mkdir(parents=True)\n    for name, text in BASE_FILES.items():\n        (repo / name).write_text(text)\n    wt.git(repo, \"init\", \"-q\", \"-b\", \"main\")\n    wt.git(repo, \"-c\", \"user.name=t\", \"-c\", \"user.email=t@example.com\", \"add\", \"-A\")\n    wt.git(repo, \"-c\", \"user.name=t\", \"-c\", \"user.email=t@example.com\", \"commit\", \"-qm\", \"base\")\n    return repo\n\n\ndef append(worktree: Path, name: str, text: str):\n    with open(worktree / name, \"a\") as f:\n        f.write(text)\n\n\ndef worker_after_hours(w: Path):\n    append(w, \"triage.py\", '\\n\\ndef after_hours_message():\\n    return \"The clinic is closed. In an emergency call 108.\"\\n')\n    append(w, \"test_triage.py\", '\\n\\ndef test_after_hours():\\n    from triage import after_hours_message\\n    assert \"108\" in after_hours_message()\\n')\n\n\ndef worker_rupees(w: Path):\n    append(w, \"billing.py\", '\\n\\ndef format_rupees(n):\\n    return f\"Rs {n}\"\\n')\n    append(w, \"test_billing.py\", '\\n\\ndef test_rupees():\\n    from billing import format_rupees\\n    assert format_rupees(450) == \"Rs 450\"\\n')\n\n\ndef worker_emergency_words(w: Path):     # a third task that also edits triage.py\n    p = w / \"triage.py\"\n    p.write_text(p.read_text().replace('\"chest pain\" in msg.lower()', '(\"chest pain\" in msg.lower() or \"unconscious\" in msg.lower())'))\n\n\ndef run_parallel(repo: Path, jobs: dict, owns: dict) -> dict:\n    \"\"\"jobs: {task: worker function}; owns: {task: [files]}. Returns a report.\"\"\"\n    report = {\"overlaps\": wt.overlaps(owns), \"violations\": {}, \"merged\": {}, \"conflicts\": {}}\n    base = wt.current_branch(repo)\n    trees = {t: wt.add_worktree(repo, t) for t in jobs}\n    threads = [threading.Thread(target=jobs[t], args=(trees[t],)) for t in jobs]\n    [th.start() for th in threads]\n    [th.join() for th in threads]\n    for t, path in trees.items():\n        wt.commit_all(path, f\"{t}\")\n        report[\"violations\"][t] = wt.violations(owns[t], wt.changed_files(path, base))\n    for t in jobs:\n        ok, conflicts = wt.merge_branch(repo, f\"worktree-{t}\")\n        report[\"merged\"][t], report[\"conflicts\"][t] = ok, conflicts\n    for t, path in trees.items():\n        wt.remove_worktree(repo, path, f\"worktree-{t}\")\n    return report\n\n\ndef pytest_summary(repo: Path) -> str:\n    p = subprocess.run([sys.executable, \"-m\", \"pytest\", \"-q\", \"-p\", \"no:cacheprovider\"], cwd=repo, capture_output=True, text=True)\n    return (p.stdout.strip().splitlines() or [\"(no output)\"])[-1]\n\n\nif __name__ == \"__main__\":\n    OWNS = {\"after-hours\": [\"triage.py\", \"test_triage.py\"], \"rupees\": [\"billing.py\", \"test_billing.py\"], \"emergency-words\": [\"triage.py\"]}\n    with tempfile.TemporaryDirectory() as d:\n        print(\"== A. two tasks that own different files\")\n        repo = make_repo(Path(d) / \"a\")\n        r = run_parallel(repo, {\"after-hours\": worker_after_hours, \"rupees\": worker_rupees}, {k: OWNS[k] for k in (\"after-hours\", \"rupees\")})\n        print(\"  overlap check:\", r[\"overlaps\"] or \"none\")\n        print(\"  outside own files:\", r[\"violations\"])\n        print(\"  merged:\", r[\"merged\"], \"| tests on the result:\", pytest_summary(repo))\n        print(\"\\n== B. two tasks that both own triage.py\")\n        owns_b = {k: OWNS[k] for k in (\"after-hours\", \"emergency-words\")}\n        print(\"  overlap check BEFORE starting:\", wt.overlaps(owns_b))\n        repo = make_repo(Path(d) / \"b\")\n        r = run_parallel(repo, {\"after-hours\": worker_after_hours, \"emergency-words\": worker_emergency_words}, owns_b)\n        print(\"  if we ignore the warning, merged:\", r[\"merged\"], \"| conflicts:\", r[\"conflicts\"])\n","ch42/README.md":"# Chapter 42 · Your agentic development team\n\n| file | what it is |\n| --- | --- |\n| `starter/.claude/agents/` | four subagent definitions: planner, coder, tester, reviewer (the reviewer and planner cannot edit) |\n| `agents_check.py` | checks them against the rules on Claude Code's sub-agents page (read 5 Nov 2026) |\n| `worktrees.py` | git worktree helpers and the file-ownership checks |\n| `parallel_demo.py` | two stand-in workers in real git worktrees, merged; then a collision |\n| `handoff.py`, `demo_handoff.py` | a handoff note as data, with validation and a human-checkpoint rule |\n\n    python -m pytest -q          # 15 tests; needs git\n    python parallel_demo.py\n    python agents_check.py starter/.claude/agents --readonly planner,reviewer\n\nThe workers in `parallel_demo.py` are scripts that write fixed changes. Git, the ownership check and the tests are real; **no real AI agent was run**.\nThe four agent files are checked against the documented format but have not been loaded into a live Claude Code session.\n","ch42/starter/.claude/agents/coder.md":"---\nname: coder\ndescription: Implements one planned task in small steps, with a test first. Use after the plan is approved; give it the plan and the list of files it may touch.\ntools: Read, Edit, Write, Bash, Grep, Glob\nmodel: sonnet\nisolation: worktree\nmaxTurns: 40\n---\n\nYou implement exactly the plan you are given, in its own git worktree.\n\n- Write a failing test first, then the code, then run the test command from AGENTS.md.\n- Touch only the files in the plan. If you need another file, stop and say why.\n- Finish with a handoff note: what you changed, how to verify it (exact commands), and open questions.\n- Never edit or delete an assertion to make a test pass.\n","ch42/starter/.claude/agents/planner.md":"---\nname: planner\ndescription: Reads the code and writes a short implementation plan. Use first for any task that touches more than two files, before anyone edits anything.\ntools: Read, Grep, Glob\nmodel: sonnet\n---\n\nYou plan; you never edit.\n\n1. Read AGENTS.md and the files the task mentions.\n2. Reply with a plan of at most 15 lines: which files change, in what order, which tests prove it, and what could go wrong.\n3. List every file the work will touch under the heading \"Files\". The coder may touch only those.\n4. If the task is unclear, list your questions instead of guessing.\n","ch42/starter/.claude/agents/reviewer.md":"---\nname: reviewer\ndescription: Reviews a diff against the plan and the rules in AGENTS.md without having seen the code being written. Use proactively after the coder finishes; it cannot edit files.\ntools: Read, Grep, Glob\nmodel: sonnet\n---\n\nYou review; you never edit. You have not seen the conversation that produced this change, which is the point.\n\nCheck, in this order:\n1. Does the diff do what the plan says, and nothing else?\n2. Do the rules in AGENTS.md still hold (read-only tools, emergencies never reach a model, limits only in config.py)?\n3. Does every new behaviour have a test, and were any assertions removed or loosened?\n4. Edge cases: empty input, an unknown name, a message with a patient identifier.\nReply with APPROVE, or a numbered list of problems that affect correctness. Skip style.\n","ch42/starter/.claude/agents/tester.md":"---\nname: tester\ndescription: Runs the project's checks and reports the exact commands and output. Use after each change, and before review, to get evidence instead of a summary.\ntools: Read, Grep, Glob, Bash\nmodel: haiku\n---\n\nRun the commands in AGENTS.md (tests, then the helpdesk evaluation).\nReport, for each command: the command, the exit code, and the last 10 lines of output.\nFor a failure, include the full assertion message. Do not fix anything and do not edit files.\n","ch42/test_ch42.py":"from pathlib import Path\n\nimport pytest\n\nimport agents_check as ac\nimport handoff as hf\nimport parallel_demo as pd\nimport worktrees as wt\n\nHERE = Path(__file__).resolve().parent\nAGENTS = HERE / \"starter\" / \".claude\" / \"agents\"\n\n\n# ---------- subagent definition files ----------\ndef test_starter_helpers_pass_and_reviewer_cannot_edit():\n    assert ac.check_folder(AGENTS, {\"planner\", \"reviewer\"}) == [\"OK    4 helper(s), no problems found.\"]\n    text = (AGENTS / \"reviewer.md\").read_text()\n    assert \"tools: Read, Grep, Glob\" in text and \"Edit\" not in text.split(\"---\")[1]\n\n\ndef write_agent(tmp_path, name, header, body=\"Do the job.\\n\"):\n    d = tmp_path / \"agents\"\n    d.mkdir(exist_ok=True)\n    (d / f\"{name}.md\").write_text(f\"---\\n{header}\\n---\\n{body}\")\n    return d\n\n\ndef test_reviewer_that_can_edit_is_an_error(tmp_path):\n    d = write_agent(tmp_path, \"reviewer\", \"name: reviewer\\ndescription: Use after changes to review.\\ntools: Read, Edit\")\n    assert any(l.startswith(\"ERROR\") and \"read-only\" in l for l in ac.check_folder(d, {\"reviewer\"}))\n\n\ndef test_missing_tools_description_and_unknown_fields_are_flagged(tmp_path):\n    d = write_agent(tmp_path, \"helper\", \"name: Helper_X\\ndescription: Helps.\\nmodle: haiku\\nmodel: gpt-9\\nisolation: vm\")\n    text = \"\\n\".join(ac.check_folder(d))\n    for needle in (\"lowercase\", \"unknown field 'modle'\", \"WHEN to use\", \"no 'tools' list\", \"model 'gpt-9'\", \"isolation 'vm'\", \"differs from the file name\"):\n        assert needle in text, needle\n\n\ndef test_header_and_body_are_required(tmp_path):\n    d = tmp_path / \"agents\"\n    d.mkdir()\n    (d / \"a.md\").write_text(\"no header here\")\n    (d / \"b.md\").write_text(\"---\\nname: b\\ndescription: Use now.\\ntools: Read\\n---\\n\")\n    text = \"\\n\".join(ac.check_folder(d))\n    assert \"must start with a --- header\" in text and \"no instructions\" in text\n\n\ndef test_duplicate_names_are_an_error(tmp_path):\n    d = write_agent(tmp_path, \"one\", \"name: same\\ndescription: Use a.\\ntools: Read\")\n    write_agent(tmp_path, \"two\", \"name: same\\ndescription: Use b.\\ntools: Read\")\n    assert any(\"two helpers are called 'same'\" in l for l in ac.check_folder(d))\n\n\n# ---------- ownership ----------\ndef test_overlaps_detects_shared_files_folders_and_globs():\n    owns = {\"a\": [\"src/triage.py\", \"tests/\"], \"b\": [\"src/billing.py\", \"tests/test_x.py\"], \"c\": [\"src/*.py\"], \"d\": [\"docs/\"]}\n    pairs = {(a, b) for a, b, _ in wt.overlaps(owns)}\n    assert pairs == {(\"a\", \"b\"), (\"a\", \"c\"), (\"b\", \"c\")}\n\n\ndef test_violations_lists_files_outside_ownership():\n    assert wt.violations([\"src/\", \"tests/test_a.py\"], [\"src/x.py\", \"tests/test_a.py\", \"tests/test_b.py\", \"README.md\"]) == [\"tests/test_b.py\", \"README.md\"]\n\n\n# ---------- real git worktrees ----------\ndef test_parallel_workers_on_different_files_merge_cleanly_and_tests_pass(tmp_path):\n    repo = pd.make_repo(tmp_path / \"r\")\n    owns = {\"after-hours\": [\"triage.py\", \"test_triage.py\"], \"rupees\": [\"billing.py\", \"test_billing.py\"]}\n    r = pd.run_parallel(repo, {\"after-hours\": pd.worker_after_hours, \"rupees\": pd.worker_rupees}, owns)\n    assert r[\"overlaps\"] == [] and r[\"violations\"] == {\"after-hours\": [], \"rupees\": []}\n    assert r[\"merged\"] == {\"after-hours\": True, \"rupees\": True}\n    assert pd.pytest_summary(repo).startswith(\"4 passed\")\n    assert \"wt-\" not in wt.git(repo, \"worktree\", \"list\").stdout          # worktrees were removed\n    assert \"worktree-rupees\" not in wt.git(repo, \"branch\").stdout\n\n\ndef test_overlap_is_caught_before_and_the_merge_conflict_is_real(tmp_path):\n    owns = {\"after-hours\": [\"triage.py\", \"test_triage.py\"], \"emergency-words\": [\"triage.py\"]}\n    assert wt.overlaps(owns) == [(\"after-hours\", \"emergency-words\", [\"triage.py\"])]\n    repo = pd.make_repo(tmp_path / \"r\")\n    r = pd.run_parallel(repo, {\"after-hours\": pd.worker_after_hours, \"emergency-words\": pd.worker_emergency_words}, owns)\n    assert r[\"merged\"][\"after-hours\"] and not r[\"merged\"][\"emergency-words\"]\n    assert r[\"conflicts\"][\"emergency-words\"] == [\"triage.py\"]\n    assert wt.git(repo, \"status\", \"--porcelain\").stdout.strip() == \"\"      # the failed merge was aborted, nothing half-merged\n\n\ndef test_a_worker_touching_a_file_it_does_not_own_is_reported(tmp_path):\n    repo = pd.make_repo(tmp_path / \"r\")\n\n    def greedy(w):\n        pd.worker_rupees(w)\n        (w / \"triage.py\").write_text((w / \"triage.py\").read_text() + \"# sneaky\\n\")\n    r = pd.run_parallel(repo, {\"rupees\": greedy}, {\"rupees\": [\"billing.py\", \"test_billing.py\"]})\n    assert r[\"violations\"][\"rupees\"] == [\"triage.py\"]\n\n\n# ---------- handoff notes ----------\ndef good_note(**kw):\n    base = dict(task=\"T1\", from_role=\"coder\", to_role=\"reviewer\", goal=\"Add an after-hours message tool to the helpdesk\",\n                done=[\"added after_hours_message()\", \"added a test that failed first\"], decisions=[\"no model call: a fixed string is safer\"],\n                files_changed=[\"triage.py\", \"test_triage.py\"], verify=[\"python -m pytest -q\"], evidence=\"$ python -m pytest -q\\n[PASS exit=0 1.1s]\\n3 passed in 0.02s\",\n                tokens_used=42_000)\n    base.update(kw)\n    return hf.Handoff(**base)\n\n\ndef test_good_note_is_valid_and_needs_no_person():\n    n = good_note()\n    assert hf.validate(n, owned=[\"triage.py\", \"test_triage.py\"]) == []\n    assert hf.checkpoint(n) == (False, [])\n\n\ndef test_vague_note_is_rejected():\n    n = good_note(verify=[], evidence=\"all tests pass\", done=[], goal=\"fix it\")\n    problems = \"\\n\".join(hf.validate(n))\n    for needle in (\"goal is too short\", \"no verify commands\", \"'done' is empty\"):\n        assert needle in problems\n    assert \"evidence is a claim\" in \"\\n\".join(hf.validate(good_note(evidence=\"all tests pass\")))\n    assert \"no evidence\" in \"\\n\".join(hf.validate(good_note(evidence=\"\")))\n\n\ndef test_outside_ownership_and_status_rules():\n    assert \"outside what this task owns\" in \"\\n\".join(hf.validate(good_note(files_changed=[\"billing.py\"]), owned=[\"triage.py\"]))\n    assert \"status must be\" in \"\\n\".join(hf.validate(good_note(status=\"finished\")))\n    assert \"no open question\" in \"\\n\".join(hf.validate(good_note(status=\"blocked\")))\n\n\ndef test_checkpoint_asks_a_person_when_risk_is_high():\n    need, why = hf.checkpoint(good_note(files_changed=[\".github/workflows/ci.yml\"], risks=[\"changes CI\"], open_questions=[\"ok to skip lint?\"], tokens_used=900_000))\n    assert need and len(why) == 4\n    assert hf.checkpoint(good_note(status=\"needs_human\"))[0]\n\n\ndef test_roundtrip_and_markdown():\n    n = good_note()\n    assert hf.Handoff.from_json(n.to_json()) == n\n    md = n.to_markdown()\n    assert md.startswith(\"# Handoff T1: coder -> reviewer  [ready]\") and \"`python -m pytest -q`\" in md and \"Tokens used: 42,000\" in md\n","ch42/worktrees.py":"\"\"\"Run several workers in parallel on one repository without letting them step on each other.\n\nGit worktrees give each worker its own folder and branch, sharing one history. This file wraps the few git\ncommands needed (all documented in git's own manual) and adds the check that matters most: who OWNS which\nfiles. Two workers that edit the same file will collide when you merge, however clever they are.\n\n    from worktrees import add_worktree, changed_files, merge_branch, remove_worktree, overlaps, violations\n\"\"\"\nfrom __future__ import annotations\n\nimport fnmatch\nimport subprocess\nfrom pathlib import Path\n\n\ndef git(repo: str | Path, *args: str, check: bool = True) -> subprocess.CompletedProcess:\n    return subprocess.run([\"git\", \"-C\", str(repo), *args], capture_output=True, text=True, check=check)\n\n\ndef current_branch(repo) -> str:\n    return git(repo, \"rev-parse\", \"--abbrev-ref\", \"HEAD\").stdout.strip()\n\n\ndef add_worktree(repo: str | Path, name: str, base: str = \"HEAD\") -> Path:\n    \"\"\"A new folder next to the repository, on a new branch worktree-<name>, starting from `base`.\"\"\"\n    path = Path(repo).resolve().parent / f\"{Path(repo).name}-wt-{name}\"\n    git(repo, \"worktree\", \"add\", \"-b\", f\"worktree-{name}\", str(path), base)\n    return path\n\n\ndef commit_all(worktree: str | Path, message: str) -> bool:\n    git(worktree, \"add\", \"-A\")\n    if not git(worktree, \"status\", \"--porcelain\").stdout.strip():\n        return False\n    git(worktree, \"-c\", \"user.name=agent\", \"-c\", \"user.email=agent@example.com\", \"commit\", \"-qm\", message)\n    return True\n\n\ndef changed_files(worktree: str | Path, base: str) -> list[str]:\n    \"\"\"Files changed on this branch since it left `base`.\"\"\"\n    return sorted(git(worktree, \"diff\", \"--name-only\", f\"{base}...HEAD\").stdout.split())\n\n\ndef merge_branch(repo: str | Path, branch: str) -> tuple[bool, list[str]]:\n    \"\"\"Merge a branch into the repository's current branch. Returns (clean, conflicted files); aborts on conflict.\"\"\"\n    r = git(repo, \"-c\", \"user.name=agent\", \"-c\", \"user.email=agent@example.com\", \"merge\", \"--no-ff\", \"-m\", f\"merge {branch}\", branch, check=False)\n    if r.returncode == 0:\n        return True, []\n    conflicts = sorted(git(repo, \"diff\", \"--name-only\", \"--diff-filter=U\").stdout.split())\n    git(repo, \"merge\", \"--abort\", check=False)\n    return False, conflicts\n\n\ndef remove_worktree(repo: str | Path, path: str | Path, branch: str | None = None) -> None:\n    git(repo, \"worktree\", \"remove\", \"--force\", str(path))\n    if branch:\n        git(repo, \"branch\", \"-D\", branch, check=False)\n\n\n# ---------------------------------------------------------------- ownership\ndef _match(a: str, b: str) -> bool:\n    \"\"\"Do two ownership patterns (a path, a folder ending in /, or a glob) cover any common file?\"\"\"\n    if a == b:\n        return True\n    for x, y in ((a, b), (b, a)):\n        if x.endswith(\"/\") and y.startswith(x):\n            return True\n        if fnmatch.fnmatch(y, x):\n            return True\n    return False\n\n\ndef overlaps(tasks: dict[str, list[str]]) -> list[tuple[str, str, list[str]]]:\n    \"\"\"Pairs of tasks whose owned files overlap: [(task_a, task_b, [patterns])]. Run this BEFORE starting parallel work.\"\"\"\n    names, out = sorted(tasks), []\n    for i, a in enumerate(names):\n        for b in names[i + 1:]:\n            common = sorted({f\"{p} ~ {q}\" if p != q else p for p in tasks[a] for q in tasks[b] if _match(p, q)})\n            if common:\n                out.append((a, b, common))\n    return out\n\n\ndef violations(owned: list[str], changed: list[str]) -> list[str]:\n    \"\"\"Files a worker changed that it does not own.\"\"\"\n    return [f for f in changed if not any(f == p or (p.endswith(\"/\") and f.startswith(p)) or fnmatch.fnmatch(f, p) for p in owned)]\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
